@* FlowControls — zoom in / zoom out / fit view / lock, stacked in a corner of the canvas. Place it
   inside FlowCanvas' ChildContent. Built from Lumeo Buttons (Outline, icon size); any ChildContent
   is appended as extra buttons. data-flow-overlay keeps the canvas engine from treating a press
   here as a pan. *@

<div data-slot="flow-controls"
     data-flow-overlay
     role="toolbar"
     aria-label="@L["Flow.Controls"]"
     aria-orientation="@(Horizontal ? "horizontal" : "vertical")"
     class="@RootClass"
     style="position:absolute;z-index:5;"
     @attributes="AdditionalAttributes">
    @if (ShowZoom)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.ZoomIn"]" title="@L["Flow.ZoomIn"]"
                Disabled="@(!CanZoomIn)" OnClick="ZoomInAsync">
            <SvgGlyph Svg="@(LumeoIcons.Plus)" class="size-4" />
        </Button>
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.ZoomOut"]" title="@L["Flow.ZoomOut"]"
                Disabled="@(!CanZoomOut)" OnClick="ZoomOutAsync">
            <SvgGlyph Svg="@(LumeoIcons.Minus)" class="size-4" />
        </Button>
    }
    @if (ShowFitView)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.FitView"]" title="@L["Flow.FitView"]"
                OnClick="FitViewAsync">
            <SvgGlyph Svg="@(LumeoIcons.Maximize2)" class="size-4" />
        </Button>
    }
    @if (ShowLock)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon"
                Class="@Cx.Merge("size-8 bg-card", Cx.When(Locked, "bg-accent text-accent-foreground"))"
                aria-label="@L["Flow.Lock"]" title="@L["Flow.Lock"]"
                aria-pressed="@(Locked ? "true" : "false")"
                OnClick="ToggleLockAsync">
            <SvgGlyph Svg="@(LumeoIcons.Lock)" class="size-4" />
        </Button>
    }
    @if (ShowSnapToggle)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon"
                Class="@Cx.Merge("size-8 bg-card", Cx.When(SnapToGrid, "bg-accent text-accent-foreground"))"
                aria-label="@L["Flow.SnapToGrid"]" title="@L["Flow.SnapToGrid"]"
                aria-pressed="@(SnapToGrid ? "true" : "false")"
                OnClick="ToggleSnapAsync">
            <SvgGlyph Svg="@(LumeoIcons.LayoutGrid)" class="size-4" />
        </Button>
    }
    @if (ShowHistory)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.Undo"]" title="@L["Flow.Undo"]"
                Disabled="@(!CanUndo)" OnClick="UndoAsync">
            <SvgGlyph Svg="@(LumeoIcons.Undo)" class="size-4" />
        </Button>
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.Redo"]" title="@L["Flow.Redo"]"
                Disabled="@(!CanRedo)" OnClick="RedoAsync">
            <SvgGlyph Svg="@(LumeoIcons.Redo)" class="size-4" />
        </Button>
    }
    @ChildContent
</div>

@code {
    [CascadingParameter] private FlowCanvas.FlowCanvasContext? Context { get; set; }

    /// <summary>Where the controls sit inside the canvas.</summary>
    public enum ControlsPosition { TopLeft, TopRight, BottomLeft, BottomRight }

    /// <summary>The corner the controls sit in.</summary>
    [Parameter] public ControlsPosition Position { get; set; } = ControlsPosition.BottomLeft;

    /// <summary>Lays the buttons out in a row instead of a column.</summary>
    [Parameter] public bool Horizontal { get; set; }

    /// <summary>Shows the zoom in / zoom out buttons.</summary>
    [Parameter] public bool ShowZoom { get; set; } = true;

    /// <summary>Shows the fit-view button.</summary>
    [Parameter] public bool ShowFitView { get; set; } = true;

    /// <summary>Shows the lock toggle (locked = nodes cannot be moved; pan and zoom still work).</summary>
    [Parameter] public bool ShowLock { get; set; } = true;

    /// <summary>Shows a grid-icon toggle bound to the canvas' <c>SnapToGrid</c>.</summary>
    [Parameter] public bool ShowSnapToggle { get; set; }

    /// <summary>Shows undo/redo buttons driven by the canvas' <c>History</c> (disabled with nothing to undo/redo, or when the canvas has no <c>History</c> set).</summary>
    [Parameter] public bool ShowHistory { get; set; }

    /// <summary>Extra buttons appended after the built-in ones.</summary>
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes merged onto the toolbar.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the toolbar.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private bool Locked => Context?.Locked == true;
    private bool SnapToGrid => Context?.SnapToGrid == true;
    private double Zoom => Context?.Viewport.Zoom ?? 1;
    private bool CanZoomIn => Context is null || Zoom < Context.MaxZoom - 1e-9;
    private bool CanZoomOut => Context is null || Zoom > Context.MinZoom + 1e-9;
    private bool CanUndo => Context?.Canvas.History?.CanUndo == true;
    private bool CanRedo => Context?.Canvas.History?.CanRedo == true;

    private string RootClass => Cx.Merge(
        "flex gap-1 rounded-md",
        Horizontal ? "flex-row" : "flex-col",
        Position switch
        {
            ControlsPosition.TopLeft => "left-3 top-3",
            ControlsPosition.TopRight => "right-3 top-3",
            ControlsPosition.BottomRight => "right-3 bottom-3",
            _ => "left-3 bottom-3",
        },
        Class);

    private Task ZoomInAsync() => Context?.Canvas.ZoomInAsync() ?? Task.CompletedTask;
    private Task ZoomOutAsync() => Context?.Canvas.ZoomOutAsync() ?? Task.CompletedTask;
    private Task FitViewAsync() => Context?.Canvas.FitViewAsync() ?? Task.CompletedTask;
    private Task ToggleLockAsync() => Context?.Canvas.SetLockedAsync(!Locked) ?? Task.CompletedTask;
    private Task ToggleSnapAsync() => Context?.Canvas.SetSnapToGridAsync(!SnapToGrid) ?? Task.CompletedTask;
    private Task UndoAsync() => Context?.Canvas.UndoAsync() ?? Task.CompletedTask;
    private Task RedoAsync() => Context?.Canvas.RedoAsync() ?? Task.CompletedTask;
}

@namespace Lumeo
@using System.ComponentModel
@using System.Globalization
@using Microsoft.AspNetCore.Components.Rendering
@inject Lumeo.Services.Localization.ILumeoLocalizer L
@attribute [EditorBrowsable(EditorBrowsableState.Never)]

@* FlowEdgeLayer — one <path> per edge, in flow coordinates, inside FlowCanvas' viewport layer, plus
   a sibling div per labelled edge (no <foreignObject> — a positioned div is simpler and themeable).
   Rendered by FlowCanvas; not meant to be used directly.

   The <svg> is zero-sized with overflow: visible so it never intercepts pointer events or affects
   layout; paths are drawn from FlowGeometry. While a node is dragged the engine rewrites the `d`
   of every connected path (and moves the matching label div) with its JS port of the same math,
   keyed by the data-source/data-target/data-*-handle/data-edge-type attributes below — keep those
   in sync with flow.js. A path's own pointer-events override the layer's "none" so it can be
   clicked/selected without the (invisible, 1x1) layer intercepting the rest of the pane.

   Phase 5 sub-flows: an edge whose deeper end sits inside a group (nesting level N > 0) is drawn in
   an extra, raised <svg data-slot="flow-edges-raised"> with z-index N — above its group (which
   stacks at N - 1) and below the nested nodes (which stack at N and come later in the DOM). Without
   that a group's tinted background would cover the edges between its own children.
   data-sa/data-ta stamp each end's anchor ("x|y|position") so the engine can still redraw an edge
   whose OTHER end is not mounted (virtualization) while its mounted end is dragged. *@

<svg data-slot="flow-edges"
     aria-hidden="true"
     class="@Cx.Merge("lumeo-flow-edges", Class)"
     style="position:absolute;left:0;top:0;width:1px;height:1px;overflow:visible;pointer-events:none;"
     @attributes="AdditionalAttributes">
    <defs>
        <marker id="@_markerId" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse" markerUnits="userSpaceOnUse">
            <path d="M0,0 L8,4 L0,8 Z" fill="var(--color-muted-foreground)" />
        </marker>
    </defs>
    @if (Context is not null)
    {
        RenderEdges(__builder, 0);
    }
</svg>
@if (Context is not null && Context.Canvas.MaxEdgeLevel > 0)
{
    @for (var level = 1; level <= Context.Canvas.MaxEdgeLevel; level++)
    {
        var lvl = level;
        <svg @key="@("raised-" + lvl)"
             data-slot="flow-edges-raised"
             data-level="@lvl.ToString(CultureInfo.InvariantCulture)"
             aria-hidden="true"
             style="@("position:absolute;left:0;top:0;width:1px;height:1px;overflow:visible;pointer-events:none;z-index:" + lvl.ToString(CultureInfo.InvariantCulture) + ";")">
            @{ RenderEdges(__builder, lvl); }
        </svg>
    }
}
@if (Context is not null)
{
    <div data-slot="flow-edge-labels" style="position:absolute;left:0;top:0;">
        @foreach (var (edge, path, _, _) in Edges)
        {
            var editable = Context.Canvas.EdgeLabelEditable;
            var editingThis = editable && _editingEdgeId == edge.Id;
            // Still requires an existing Label/EdgeLabelTemplate (or an edit already in flight) to
            // render at all — EdgeLabelEditable alone must NOT put an always-present, always-hit-
            // testable div at every edge's midpoint: a genuinely empty one there would silently eat
            // the click a bare edge (no label) otherwise needs for on-path selection.
            if (!editingThis && Context.Canvas.EdgeLabelTemplate is null && string.IsNullOrEmpty(edge.Label)) continue;
            <div @key="@("label-" + edge.Id)"
                 data-flow-edge-label
                 data-flow-nodrag
                 data-edge-id="@edge.Id"
                 style="@LabelStyle(path, Context.Canvas.EdgeLevel(edge))"
                 @ondblclick="@(() => BeginEdit(edge))">
                @if (editingThis)
                {
                    <div @onclick:stopPropagation="true" style="min-width:6rem;">
                        <Input @bind-Value="_editText" Size="Lumeo.Size.Sm" AutoFocus="true" aria-label="@L["Flow.EdgeLabelEdit"]"
                               @onkeydown="@(e => HandleEditKeyDownAsync(e, edge))" />
                    </div>
                }
                else if (Context.Canvas.EdgeLabelTemplate is not null)
                {
                    @Context.Canvas.EdgeLabelTemplate(new FlowEdgeContext(edge, Context.Canvas.IsEdgeSelected(edge.Id), path.LabelX, path.LabelY))
                }
                else
                {
                    <span class="rounded border border-border bg-card px-1.5 py-0.5 text-[10px] text-card-foreground shadow-sm">@edge.Label</span>
                }
            </div>
        }
    </div>
}

@code {
    [CascadingParameter] private FlowCanvas.FlowCanvasContext? Context { get; set; }

    /// <summary>Additional CSS classes merged onto the edge layer's <c>&lt;svg&gt;</c>.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the edge layer's <c>&lt;svg&gt;</c>.</summary>
